from pathlib import Path
import sys,json,time
import polars as pl,numpy as np,lightgbm as lgb
R=Path(__file__).resolve().parents[2];O=Path(__file__).parent;P=R/'experiments/astra_011';sys.path.insert(0,str(R/'experiments/astra_baseline/src'));import evaluate_v2 as E
sys.path.insert(0,str(R/'experiments/astra_engine'));import context as C
tr=pl.read_parquet(P/'mined_train.parquet');nttr=pl.read_parquet(P/'train/ntrue.parquet');tr=tr.join(nttr,on='s1',maintain_order='left');dev=C.add(pl.read_parquet(P/'dev/parts/*.parquet'));nt=pl.read_parquet(P/'dev/ntrue.parquet');cfg=json.loads((P/'relative_evidence_decision.json').read_text());features=cfg['features'];old=lgb.Booster(model_file=str(P/'relative_evidence.txt'));pred=old.predict(dev.select(features).to_numpy(),num_threads=2);hard=(dev['label'].to_numpy()==1)|(pred>=.02);rng=np.random.default_rng(20260930);keep=hard|(rng.random(dev.height)<.1);early=dev.filter(pl.Series(keep));ew=np.where(hard[keep],1.,10.);rows=[]
for power in [.5,1.]:
 t=time.time();name=f'macro_weight_{power}';weights=tr['_weight'].to_numpy()/np.maximum(tr['ntrue'].to_numpy(),1)**power;m=lgb.LGBMClassifier(objective='binary',learning_rate=.045,num_leaves=127,min_child_samples=80,colsample_bytree=.9,subsample=.85,subsample_freq=1,n_estimators=1000,n_jobs=2,random_state=20260929,verbosity=-1)
 m.fit(tr.select(features).to_numpy(),tr['label'].to_numpy(),sample_weight=weights,feature_name=features,eval_set=[(early.select(features).to_numpy(),early['label'].to_numpy())],eval_sample_weight=[ew],eval_metric='average_precision',callbacks=[lgb.early_stopping(60,verbose=False),lgb.log_evaluation(200)]);m.booster_.save_model(str(O/f'{name}.txt'));s=dev.select('s1','src','eid','label').with_columns(pl.Series('score',m.predict_proba(dev.select(features).to_numpy())[:,1].astype('float32')));s.write_parquet(O/f'{name}_dev_scored.parquet');sw=E.sweep(s,nt,np.round(np.arange(.3,.951,.025),3));sw.write_csv(O/f'{name}_thresholds.csv');best=sw.sort('macro_f05',descending=True).row(0,named=True);out=dict(cfg);out.update(threshold=best['threshold'],dev=best,weight_power=power);(O/f'{name}_decision.json').write_text(json.dumps(out,indent=2));rows.append(dict(experiment_id=name,validation_f05=best['macro_f05'],precision=best['macro_precision'],recall=best['macro_recall'],singleton_accuracy=best['singleton_accuracy'],runtime=time.time()-t));pl.DataFrame(rows).write_csv(O/'experiments.csv');print(rows[-1],flush=True)
